sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('x_snc_trackmed.AutoMedUtils');
    ga.addParam('sysparm_name', 'getScheduleDetails');
    ga.addParam('sysparm_schedule_id', newValue);
    ga.getXMLAnswer(function(answer) {
        if (answer) {
            var result = JSON.parse(answer);
            if (result.patient) {
                g_form.setValue('patient', result.patient);
            }
            if (result.caretaker) {
                g_form.setValue('care_taker', result.caretaker);
            }
        }
    });
}
